buggy.oob_integer_conversion:
import numpy as np
from numpy import iinfo

# Test int32('2147483648') - exceeds max int32
try:
    result = np.int32('2147483648')
    probe('int32_overflow', int(result))
except OverflowError:
    probe('int32_overflow', 'OverflowError')

# Test int8('128') - exceeds max int8
try:
    result = np.int8('128')
    probe('int8_overflow', int(result))
except OverflowError:
    probe('int8_overflow', 'OverflowError')

# Test uint8('-1') - negative value for unsigned
try:
    result = np.uint8('-1')
    probe('uint8_negative', int(result))
except OverflowError:
    probe('uint8_negative', 'OverflowError')

# Test int32(str(iinfo.max + 1))
try:
    result = np.int32(str(iinfo(np.int32).max + 1))
    probe('int32_max_plus_one', int(result))
except OverflowError:
    probe('int32_max_plus_one', 'OverflowError')
